<script lang="ts">
	import UiStatePanel from '$lib/components/UiStatePanel.svelte';
	import { onMount, getContext } from 'svelte';
	import { goto } from '$app/navigation';
	import type { I18nState } from '../../../../../lib/i18n/i18n.svelte';
	import { createPosActivityState } from '../state/posActivityState.svelte';
	const i18n=getContext<I18nState>('i18n');const vm=createPosActivityState();
	onMount(()=>{void vm.load();});
	function change<K extends keyof typeof vm.query>(key:K,value:(typeof vm.query)[K]){vm.set(key,value);void vm.load();}
	function money(c:number){return new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(c/100);}
	function dateTime(v:string|null){return v?new Date(v).toLocaleString(): '—';}
	function goOrder(id:number){void goto('/management/sales-orders/'+id);}
</script>
<section class="page">
	<header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Actividad POS')}</h1><p>{i18n.t('Resumen de ventas, reembolsos y transacciones del punto de venta.')}</p></div><button onclick={()=>void vm.load()}>{i18n.t('Actualizar')}</button></header>
	<div class="filters">
		<label>{i18n.t('Fecha')}<input type="date" value={vm.query.date??''} onchange={e=>change('date',e.currentTarget.value)}/></label>
		<label>{i18n.t('Tipo')}<select value={vm.query.orderType??'sale'} onchange={e=>change('orderType',e.currentTarget.value as 'sale'|'refund'|'all')}><option value="sale">{i18n.t('Ventas')}</option><option value="refund">{i18n.t('Reembolsos')}</option><option value="all">{i18n.t('Todos')}</option></select></label>
		<label>{i18n.t('Canal')}<select value={vm.query.channel??''} onchange={e=>change('channel',(e.currentTarget.value||null) as 'counter'|'phone'|null)}><option value="">{i18n.t('Todos')}</option><option value="counter">{i18n.t('Mostrador')}</option><option value="phone">{i18n.t('Teléfono')}</option></select></label>
		<label>{i18n.t('Estado')}<select value={vm.query.status??''} onchange={e=>change('status',e.currentTarget.value||null)}><option value="">{i18n.t('Todos')}</option>{#each ['OPEN','ALLOCATED','PICKED','PACKED','SHIPPED','CANCELLED'] as status}<option value={status}>{status}</option>{/each}</select></label>
		<label>{i18n.t('Terminal')}<input value={vm.query.terminalId??''} oninput={e=>vm.set('terminalId',e.currentTarget.value||null)} onkeydown={e=>{if(e.key==='Enter')void vm.loadList();}} placeholder={i18n.t('Filtrar terminal')}/></label>
		<label>{i18n.t('Cajero')}<input value={vm.query.cashierId??''} oninput={e=>vm.set('cashierId',e.currentTarget.value||null)} onkeydown={e=>{if(e.key==='Enter')void vm.loadList();}} placeholder={i18n.t('ID de usuario')}/></label>
		<button class="apply" onclick={()=>void vm.loadList()}>{i18n.t('Aplicar filtros')}</button>
	</div>
	{#if vm.summaryError}<p class="error" role="alert">{vm.summaryError}</p>{/if}
	{#if vm.summary}
		<div class="kpis">
			<article><span>{i18n.t('Ventas')}</span><strong>{vm.summary.today.salesCount}</strong><small>{money(vm.summary.today.salesTotalCents)}</small></article>
			<article><span>{i18n.t('Reembolsos')}</span><strong>{vm.summary.today.refundCount}</strong><small>{money(vm.summary.today.refundTotalCents)}</small></article>
			<article><span>{i18n.t('Ingresos netos')}</span><strong>{money(vm.summary.today.netCents)}</strong><small>{i18n.t('Comparación con día anterior')}: {money(vm.summary.vsYesterdayCents)}</small></article>
			<article><span>{i18n.t('Promedio por venta')}</span><strong>{money(vm.summary.today.averageSaleCents)}</strong></article>
			<article><span>{i18n.t('Mostrador')}</span><strong>{money(vm.summary.today.counterCents)}</strong><small>{vm.summary.today.counterCount} {i18n.t('ventas')}</small></article>
			<article><span>{i18n.t('Teléfono')}</span><strong>{money(vm.summary.today.phoneCents)}</strong><small>{vm.summary.today.phoneCount} {i18n.t('ventas')}</small></article>
		</div>
		<div class="summary-grid">
			<article class="panel"><h2>{i18n.t('Comparación semanal')}</h2><div class="week">{#each vm.summary.weekThis as day,i}<div class="day"><span>{['L','M','X','J','V','S','D'][i]}</span><div class="bars"><div class="bar last" style="height:{Math.max(2,vm.summary.weekLast[i]?.netCents/(Math.max(vm.summary.weekThisTotalCents,vm.summary.weekLastTotalCents,1))*100)}%"></div><div class="bar current" style="height:{Math.max(2,day.netCents/(Math.max(vm.summary.weekThisTotalCents,vm.summary.weekLastTotalCents,1))*100)}%"></div></div><small>{money(day.netCents)}</small></div>{/each}</div><footer>{i18n.t('Esta semana')}: {money(vm.summary.weekThisTotalCents)} · {i18n.t('Semana anterior')}: {money(vm.summary.weekLastTotalCents)}</footer></article>
			<article class="panel"><h2>{i18n.t('Medios de pago')}</h2>{#if vm.summary.tenders.length===0}<p class="muted">{i18n.t('Sin datos')}</p>{:else}{#each vm.summary.tenders as tender}<div class="tender"><span>{tender.method}</span><strong>{money(tender.cents)}</strong><small>{tender.count}</small></div>{/each}{/if}<h3>{i18n.t('Terminales activas')}</h3><p>{vm.summary.activeTerminals.join(', ')||'—'}</p></article>
		</div>
	{:else if vm.summaryLoading}<UiStatePanel kind="loading" title={i18n.t('Cargando resumen POS')} message={i18n.t('Estamos calculando el resumen de actividad del punto de venta.')} />{/if}
	{#if vm.listError}<p class="error" role="alert">{vm.listError}</p>{/if}
	{#if vm.loading}<UiStatePanel kind="loading" title={i18n.t('Cargando transacciones')} message={i18n.t('Estamos recuperando las transacciones del período.')} />{:else if vm.page.salesOrders.length===0}<UiStatePanel kind="empty" title={i18n.t('Sin transacciones')} message={i18n.t('No hay transacciones para los filtros seleccionados.')} />{:else}
		<div class="table-wrap"><table><thead><tr><th>{i18n.t('Pedido')}</th><th>{i18n.t('Fecha')}</th><th>{i18n.t('Tipo')}</th><th>{i18n.t('Canal')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Terminal')}</th><th>{i18n.t('Cajero')}</th><th>{i18n.t('Cliente')}</th><th>{i18n.t('Total')}</th><th>{i18n.t('Pago')}</th><th>{i18n.t('Referencia')}</th></tr></thead><tbody>{#each vm.page.salesOrders as row (row.salesOrderId)}<tr class="clickable" onclick={()=>vm.select(row)}><td>{row.salesOrderNumber}</td><td>{dateTime(row.createdAt)}</td><td>{row.orderType}</td><td>{row.channel}</td><td>{row.status}</td><td>{row.terminalId??'—'}</td><td>{row.cashierId??'—'}</td><td>{row.customerName??i18n.t('Cliente ocasional')}</td><td>{money(row.totalCents)}</td><td>{row.paymentMethod??'—'}</td><td>{row.externalTxnRef??'—'}</td></tr>{/each}</tbody></table></div>
		<div class="pagination"><span>{vm.page.total} {i18n.t('registros')} · {i18n.t('Página')} {vm.page.page} / {vm.page.pages}</span><button disabled={vm.page.page<=1} onclick={()=>{vm.setPage(vm.page.page-1);void vm.loadList();}}>{i18n.t('Anterior')}</button><button disabled={vm.page.page>=vm.page.pages} onclick={()=>{vm.setPage(vm.page.page+1);void vm.loadList();}}>{i18n.t('Siguiente')}</button></div>
	{/if}
</section>
{#if vm.selected}<div class="overlay" role="presentation" onclick={()=>vm.select(null)}><section class="detail" role="dialog" aria-modal="true" aria-label={i18n.t('Detalle de transacción')} onclick={e=>e.stopPropagation()}><header><h2>{vm.selected.salesOrderNumber}</h2><button onclick={()=>vm.select(null)}>{i18n.t('Cerrar')}</button></header><dl><dt>{i18n.t('Tipo / Estado')}</dt><dd>{vm.selected.orderType} · {vm.selected.status}</dd><dt>{i18n.t('Fecha')}</dt><dd>{dateTime(vm.selected.createdAt)}</dd><dt>{i18n.t('Cliente')}</dt><dd>{vm.selected.customerName??'—'} · {vm.selected.customerPhone??'—'}</dd><dt>{i18n.t('Cajero')}</dt><dd>{vm.selected.cashierId??'—'}</dd><dt>{i18n.t('Terminal')}</dt><dd>{vm.selected.terminalId??'—'}</dd><dt>{i18n.t('Canal')}</dt><dd>{vm.selected.channel}</dd><dt>{i18n.t('Método de pago')}</dt><dd>{vm.selected.paymentMethod??'—'}</dd><dt>{i18n.t('Referencia externa')}</dt><dd>{vm.selected.externalTxnRef??'—'}</dd><dt>{i18n.t('Almacén')}</dt><dd>{vm.selected.warehouseId}</dd><dt>{i18n.t('Total')}</dt><dd class="total">{money(vm.selected.totalCents)}</dd></dl><button class="primary" onclick={()=>goOrder(vm.selected!.salesOrderId)}>{i18n.t('Abrir Sales Order')}</button></section></div>{/if}
<style>
.page{max-width:84rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer}button:disabled{opacity:.45}.filters{display:flex;flex-wrap:wrap;gap:.65rem;margin:1rem 0;align-items:end}.filters label{display:grid;gap:.3rem;color:var(--slate);font-size:.78rem}.filters input,.filters select{min-height:38px;border:1px solid var(--line);border-radius:8px;padding:.45rem .6rem;background:var(--card);color:var(--ink)}.apply,.primary{background:var(--accent);color:white}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:.65rem;margin:1rem 0}.kpis article,.panel{display:grid;gap:.25rem;padding:.9rem;border:1px solid var(--line);border-radius:10px;background:var(--card)}.kpis span,.kpis small,.panel footer,.muted{color:var(--slate);font-size:.75rem}.kpis strong{font:700 1.1rem var(--disp)}.summary-grid{display:grid;grid-template-columns:2fr 1fr;gap:.75rem;margin-bottom:1rem}.panel h2{font:600 1rem var(--disp);margin:0 0 .4rem}.panel h3{font:600 .85rem var(--disp);margin:.8rem 0 0}.week{height:155px;display:flex;gap:.35rem;align-items:stretch}.day{flex:1;display:grid;grid-template-rows:16px 1fr 22px;min-width:0;text-align:center}.day span,.day small{font-size:.65rem;color:var(--slate)}.bars{display:flex;align-items:end;justify-content:center;gap:3px;height:100%;border-bottom:1px solid var(--line)}.bar{width:30%;border-radius:3px 3px 0 0;min-height:2px}.last{background:var(--line)}.current{background:var(--accent)}.tender{display:flex;gap:.5rem;align-items:center;justify-content:space-between;padding:.35rem 0;border-bottom:1px solid var(--line)}.tender small{color:var(--slate)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card)}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.8rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.68rem;text-transform:uppercase}.clickable{cursor:pointer}.clickable:hover{background:var(--surface-hover)}.pagination{display:flex;justify-content:space-between;align-items:center;gap:.5rem;margin:1rem 0}.pagination span,.empty{color:var(--slate);font-size:.82rem}.error{color:var(--danger)}.overlay{position:fixed;inset:0;background:#0007;display:grid;place-items:center;padding:1rem;z-index:50}.detail{width:min(100%,34rem);max-height:90vh;overflow:auto;padding:1.1rem;border:1px solid var(--line);border-radius:14px;background:var(--card);box-shadow:0 20px 60px #0003}.detail header{margin-bottom:1rem}.detail h2{margin:0;font:700 1.1rem var(--disp)}dl{display:grid;grid-template-columns:1fr 1.4fr;gap:.55rem;padding:.5rem 0}dt{color:var(--slate);font-size:.8rem}dd{margin:0;overflow-wrap:anywhere}.total{font-weight:700}.primary{width:100%;margin-top:.5rem}@media(max-width:720px){header{align-items:flex-start;flex-direction:column}.summary-grid{grid-template-columns:1fr}.pagination{flex-wrap:wrap}.filters label{flex:1 1 130px}}
</style>